mapper.select:
SELECT distinct a.grid_id,a.grid_code,a.grid_name,DATE_FORMAT(a.create_time,'%Y-%m-%d') AS create_time, a.point_status,c.DEPT_NAME AS org_name, if(a.parent_id = 0,NULL,a.parent_id) as parent_id, a.parent_code,b.grid_name AS parent_name,a.grid_level,a.grid_sort, a.grid_area,CONCAT(DATE_FORMAT(a.grid_begin_time,'%Y-%m-%d'),' ~ ',DATE_FORMAT(a.grid_end_time,'%Y-%m-%d')) AS grid_time, a.is_end,a.grid_address,a.grid_introduce,a.regin_scope_desc FROM bm_grid a LEFT JOIN bm_grid b ON a.parent_id = b.grid_id LEFT JOIN sys_dept c ON c.DEPT_ID = a.grid_em_center and c.del_flag = '0' WHERE a.delete_flag = 0
and a.parent_id = #{parentId}
and a.grid_id != #{excludeGridId}
${dataScope} order by a.grid_sort
